<script setup lang="ts">
const ids=defineModel<string[]>({default:()=>[]})
const props=defineProps<{disabled?:boolean}>(),emit=defineEmits<{busy:[value:boolean]}>()
const auth=useAuth(),busy=ref(false),error=ref(''),input=ref<HTMLInputElement|null>(null)
async function upload(event:Event){const node=event.target as HTMLInputElement,files=Array.from(node.files||[]);node.value='';if(!files.length||props.disabled)return;busy.value=true;emit('busy',true);error.value='';try{if(ids.value.length+files.length>12)throw new Error('每条动态最多 12 张照片。');for(const file of files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw new Error('请选择不超过 5 MB 的 JPG、PNG 或 WebP 图片。');const form=new FormData();form.append('file',file);const data=await auth.request<{id:string}>('/uploads',form);ids.value=[...ids.value,data.id]}}catch(e){error.value=(e as Error).message}finally{busy.value=false;emit('busy',false)}}
</script>
<template><div><div class="upload-gallery"><div v-for="id in ids" :key="id" class="upload-gallery-item"><img :src="'/api/assets/'+id" alt="已选照片" /><button type="button" :disabled="busy||disabled" @click="ids=ids.filter(item=>item!==id)">移除</button></div><button type="button" class="upload-square" :disabled="busy||disabled||ids.length>=12" @click="input?.click()"><AppIcon name="plus" :size="26" /><span>{{ busy?'上传中…':'添加照片' }}</span></button></div><input ref="input" type="file" hidden multiple accept="image/jpeg,image/png,image/webp" :disabled="busy||disabled" @change="upload" /><p v-if="error" class="form-error" role="alert">{{ error }}</p><small class="muted">每张最多 5 MB，最多 12 张。</small></div></template>
